window.__ModuleLoader__.load({
  id: 'dsh-store-ops-expert',
  factory(require) {
    const React = require('react');
    const h = React.createElement;
    const DASHBOARD_B64 = '';

    function openDashboard() {
      const bin = atob(DASHBOARD_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const url = URL.createObjectURL(new Blob([bytes], { type: 'text/html;charset=utf-8' }));
      window.open(url, '_blank', 'noopener');
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    }

    function DashboardButton() {
      const [hover, setHover] = React.useState(false);
      return h('button', {
        type: 'button',
        onClick: openDashboard,
        title: '打开经营看板（单文件、本地数据、不上传）',
        onMouseEnter: () => setHover(true),
        onMouseLeave: () => setHover(false),
        style: {
          display: 'inline-flex', alignItems: 'center', gap: 6,
          height: 30, padding: '0 10px', borderRadius: 8,
          border: '1px solid var(--dsw-alias-border-secondary, #d5d5d5)',
          background: hover ? 'var(--dsw-alias-bg-hover, #f4f4f4)' : 'transparent',
          color: 'var(--dsw-alias-text-primary, #1f2a2a)',
          fontSize: 12, cursor: 'pointer', fontFamily: 'inherit',
        },
      }, h('span', { 'aria-hidden': true, style: { fontSize: 14, lineHeight: 1 } }, '▦'), '经营看板');
    }

    return {
      inject: ['slots'],
      apply(ctx) {
        ctx.slots.inject('conversation.composer.dock', () => ctx.slots.register({
          name: 'conversation.composer.dock',
          id: 'store-ops-dashboard',
          order: 20,
        }, DashboardButton));
      },
    };
  },
});
